public class HeapTree {
    private int[] heap;
    private int size;

    public HeapTree(int capacity) {
        heap = new int[capacity];
        size = 0;
    }

    public int get() {
        return heap[0];
    }
}

public void insert(int element) {
    heap[size++] = element;
    heapifyUp(size - 1);
}

public int delete() {
    int root = heap[0];
    heap[0] = heap[size - 1];
    size--;
    heapifyDown(0);
    return root;
}

private void heapifyUp(int index) {
    int parentIndex = (index - 1) / 2;

    while (index > 0 && heap[index] > heap[parentIndex]) {
        swap(index, parentIndex);
        index = parentIndex;
        parentIndex = (index - 1) / 2;
    }
}

private void heapifyDown(int index) {
    int left = 2 * index + 1;
    int right = 2 * index + 2;
    int largest = index;

    if (left < size && heap[left] > heap[largest])
        largest = left;
    if (right < size && heap[right] > heap[largest])
        largest = right;

    if (largest != index) {
        swap(index, largest);
        heapifyDown(largest);
    }
}

private AVLNode rightRotate(AVLNode y) {
    AVLNode x = y.left;
    AVLNode T2 = x.right;

    // Rotación
    x.right = y;
    y.left = T2;

    // Actualizar alturas
    y.height = Math.max(height(y.left), height(y.right)) + 1;
    x.height = Math.max(height(x.left), height(x.right)) + 1;

    return x;  // nueva raíz del subárbol
}

private AVLNode insertRecursive(AVLNode node, int key) {
    // ... inserción normal de BST (sin duplicados)
    node.height = 1 + Math.max(height(node.left),
                               height(node.right));
    int balance = getBalance(node);
    if (balance < -1 && key < node.left.key)    // LL
        return rightRotate(node);
    if (balance > 1 && key > node.right.key)    // RR
        return leftRotate(node);
    if (balance < -1 && key > node.left.key) {  // LR
        node.left = leftRotate(node.left);
        return rightRotate(node);
    }
    if (balance > 1 && key < node.right.key) {  // RL
        node.right = rightRotate(node.right);
        return leftRotate(node);
    }
    return node;
}

